    // Local-only check: skip OCSP/network so selecting a cert never stalls
    // on a slow responder or triggers a smartcard PIN prompt.
    const verifyResult = await smimeVerifyCert(
      x509cert,
      selectEncryptionCert
        ? Ci.nsIX509CertDB.verifyUsageEmailRecipient
        : Ci.nsIX509CertDB.verifyUsageEmailSigner,
      Ci.nsIX509CertDB.FLAG_LOCAL_ONLY
    );
    if (!verifyResult.ok) {
      let failureText;
      if (verifyResult.isNssError) {
        failureText = await document.l10n.formatValue(
          "configured-cert-failure-use-anyway-detail-v2",
          {
            errorMsg: verifyResult.errorMsg,
            errorCodeStr: verifyResult.errorName,
          }
        );
      } else {
        failureText = await document.l10n.formatValue(
          "configured-cert-failure-use-anyway-v2",
          { errorCode: verifyResult.errorCode }
        );
      }
      // Let the user override: a local-only failure can be a false
      // negative, e.g. an issuer CA not yet installed.
      if (!askUser(failureText)) {
        return;
      }
    }

    certInfo.disabled = false;
    certInfo.value =
      x509cert.displayName + " [" + x509cert.serialNumber + "]";
    certInfo.displayName = x509cert.displayName;
    certInfo.dbKey = x509cert.dbKey;

    if (selectEncryptionCert) {
      enableEncryptionControls(true);

      checkOtherCert(
        x509cert,
        kSigningCertPref,
        email_signing_cert_usage,
        "signing_needCertWantSame",
        "signing_wantSame",
        "signing_needCertWantToSelect",
        enableSigningControls
      );
    } else {
      enableSigningControls(true);

      checkOtherCert(
        x509cert,
        kEncryptionCertPref,
        email_recipient_cert_usage,
        "encryption_needCertWantSame",
        "encryption_wantSame",
        "encryption_needCertWantToSelect",
        enableEncryptionControls
      );
    }
  }
}

updateTechPref();
enableSelectButtons();
onSave();
